import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner keyboard = new Scanner(System.in);

        int firstInt = keyboard.nextInt();
        int secondInt = keyboard.nextInt();
        System.out.println("Part 1 int: " + (firstInt + secondInt));
        System.out.println("Part 1 long: " + ((long) firstInt + secondInt));

        long firstLong = keyboard.nextLong();
        long secondLong = keyboard.nextLong();
        int result = (int) (firstLong + secondLong);
        System.out.println("Part 2: " + result);

        int first = keyboard.nextInt();
        int second = keyboard.nextInt();
        System.out.println("Sum: " + (first + second));
        System.out.println("Difference: " + (first - second));
        System.out.println("Product: " + (first * second));
        System.out.println("Quotient: " + (first / second));
        System.out.println("Remainder: " + (first % second));

        int originalFirst = first;
        int originalSecond = second;
        result = ++first;
        System.out.println("++first: " + result);
        first = originalFirst;
        result = first++;
        System.out.println("first++: " + result);
        result = --second;
        System.out.println("--second: " + result);
        second = originalSecond;
        result = second--;
        System.out.println("second--: " + result);

        keyboard.close();
    }
}

