import java.util.Locale;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner keyboard = new Scanner(System.in);
        System.out.print("Enter the VAT percentage: ");
        double percentage = keyboard.nextDouble();
        System.out.print("Enter an amount in €: ");
        double amount = keyboard.nextDouble();
        System.out.print("Make a choice (1 = inclusive, 2 = exclusive): ");
        int choice = keyboard.nextInt();
        double factor = 1.0 + percentage / 100.0;
        if (choice == 1) {
            double exclusive = amount / factor;
            System.out.printf(Locale.US, "€%.1f + %.1f%% VAT = €%.1f%n", exclusive, percentage, amount);
        } else if (choice == 2) {
            double inclusive = amount * factor;
            System.out.printf(Locale.US, "€%.1f + %.1f%% VAT = €%.1f%n", amount, percentage, inclusive);
        } else {
            System.out.println("Invalid choice!");
        }
        keyboard.close();
    }
}

