import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final int MINIMUM = 1000;
        final int MAXIMUM = 9999;
        Scanner keyboard = new Scanner(System.in);

        while (true) {
            System.out.print("Enter a 4-digit whole number (1000..9999), or -1 to stop: ");
            int number = keyboard.nextInt();
            if (number == -1) {
                break;
            }
            if (number < MINIMUM || number > MAXIMUM) {
                System.out.println("Invalid number. Enter a value from 1000 to 9999.");
                continue;
            }

            int remaining = number;
            int sum = 0;
            while (remaining > 0) {
                sum += remaining % 10;
                remaining /= 10;
            }
            System.out.println("The sum of the digits of this number is " + sum);
        }
        keyboard.close();
    }
}

