public class Main {
    public static void main(String[] args) {
        StringBuilder line = new StringBuilder();
        int value = 120;
        while (value >= 100) { line.append(value).append(' '); value--; }
        System.out.println(line.toString().trim());

        line.setLength(0);
        value = 3;
        while (value < 50) { line.append(value).append(' '); value += 3; }
        System.out.println(line.toString().trim());

        line.setLength(0);
        value = 1;
        while (value < 10_000) { line.append(value).append(' '); value *= 5; }
        System.out.println(line.toString().trim());

        line.setLength(0);
        char letter = 'a';
        while (letter <= 'z') { line.append(letter); letter++; }
        System.out.println(line);

        // Task 2: the same sequences using do-while loops.
        line.setLength(0); value = 120;
        do { line.append(value).append(' '); value--; } while (value >= 100);
        System.out.println(line.toString().trim());
        line.setLength(0); value = 3;
        do { line.append(value).append(' '); value += 3; } while (value < 50);
        System.out.println(line.toString().trim());
        line.setLength(0); value = 1;
        do { line.append(value).append(' '); value *= 5; } while (value < 10_000);
        System.out.println(line.toString().trim());
        line.setLength(0); letter = 'a';
        do { line.append(letter); letter++; } while (letter <= 'z');
        System.out.println(line);

        // Task 3: the same sequences using for loops.
        line.setLength(0);
        for (int i = 120; i >= 100; i--) line.append(i).append(' ');
        System.out.println(line.toString().trim());
        line.setLength(0);
        for (int i = 3; i < 50; i += 3) line.append(i).append(' ');
        System.out.println(line.toString().trim());
        line.setLength(0);
        for (int i = 1; i < 10_000; i *= 5) line.append(i).append(' ');
        System.out.println(line.toString().trim());
        line.setLength(0);
        for (char i = 'a'; i <= 'z'; i++) line.append(i);
        System.out.println(line);
    }
}

