import java.util.Locale;
import java.util.Scanner;
class BankAccount {
    private String holder;
    private String iban;
    private double balance;
    public BankAccount(String holder, String iban, double balance) {
        this.holder = holder;
        this.iban = iban;
        this.balance = balance;
    }
    public BankAccount(String holder, String iban) {
        this.holder = holder;
        this.iban = iban;
        this.balance = 0;
    }

    public String getHolder() {
        return this.holder;
    }

    public String getIban() {
        return this.iban;
    }

    public double getBalance() {
        return this.balance;
    }

    public double deposit(double amount) {
        this.balance += amount;
        return this.balance;
    }

    public boolean withdraw(double amount) {
        if (balance >= amount) {
            this.balance -= amount;
            return true;
        } else {
            return false;
        }
    }

    public String toString() {
        return String.format(Locale.GERMANY, "The account %s of %s has a balance of € %.2f", this.iban, this.holder, this.balance);
    }
}
