    public static void main(String[] args) {
        Scanner keyboard = new Scanner(System.in);

        String firstHolder = keyboard.nextLine();
        String firstIban = keyboard.nextLine();
        double depositAmount = keyboard.nextDouble();
        double withdrawalAmount = keyboard.nextDouble();
        double rejectedWithdrawal = keyboard.nextDouble();

        BankAccount first = new BankAccount(firstHolder, firstIban);
        System.out.println(first);
        first.deposit(depositAmount);
        System.out.println(first);
        if (first.withdraw(withdrawalAmount)) {
